#include "BuiltinEffects.h"
#include "BuiltinGraph.h"
#include "PluginProcessor.h"
#include <stdexcept>
#include <iostream>
namespace {
using namespace drum;
void check(bool v,const char* message){if(!v)throw std::runtime_error(message);}
void set(BuiltinEffect& p,int i,float v){auto* parameter=p.controls[(size_t)i];parameter->setValueNotifyingHost(parameter->convertTo0to1(v));}
juce::AudioBuffer<float> sine(int frames,double hz=1000,double rate=48000){juce::AudioBuffer<float> b(2,frames);for(int n=0;n<frames;++n){float v=.5f*std::sin(juce::MathConstants<double>::twoPi*hz*n/rate);b.setSample(0,n,v);b.setSample(1,n,v);}return b;}
float rms(const juce::AudioBuffer<float>& b,int start){return b.getRMSLevel(0,start,b.getNumSamples()-start);}
struct Tempo:juce::AudioPlayHead {double tempo=120;juce::Optional<PositionInfo> getPosition() const override{PositionInfo p;p.setBpm(tempo);return p;}};
}
void runCreativeTests(){using namespace drum;juce::MidiBuffer midi;
    for(int type=9;type<builtinCount;++type)for(double rate:{44100.,48000.,96000.}){BuiltinEffect p((BuiltinKind)type);check(isBuiltin(builtinDescription(p.kind)) && createBuiltin(builtinDescription(p.kind))!=nullptr,"Creative effect missing from catalogue");p.prepareToPlay(rate,4096);auto input=sine(4096,2000,rate);p.processBlock(input,midi);for(int c=0;c<2;++c)for(int n=0;n<4096;++n)check(std::isfinite(input.getSample(c,n)),"Creative effect emitted nonfinite audio");p.reset();input.clear();p.processBlock(input,midi);check(input.getMagnitude(0,4096)==0,"Creative effect retained audio after reset");juce::MemoryBlock state;p.getStateInformation(state);BuiltinEffect recalled(p.kind);recalled.setStateInformation(state.getData(),(int)state.getSize());for(size_t n=0;n<p.controls.size();++n)check(recalled.controls[n]->get()==p.controls[n]->get(),"Creative effect parameters changed on recall");}
    BuiltinEffect dynamic(BuiltinKind::dynamicEq);set(dynamic,0,1000);set(dynamic,1,4);set(dynamic,2,-40);set(dynamic,3,-18);set(dynamic,4,.1f);dynamic.prepareToPlay(48000,48000);auto signal=sine(48000);dynamic.processBlock(signal,midi);check(rms(signal,24000)<.1f && dynamic.dynamicGain.load()< -15,"Dynamic EQ did not reduce the detected frequency");dynamic.reset();auto quiet=sine(48000);quiet.applyGain(.0001f);auto original=quiet;dynamic.processBlock(quiet,midi);check(std::abs(rms(quiet,24000)-rms(original,24000))<.000002f,"Dynamic EQ cut a below-threshold hit");
    BuiltinEffect crusher(BuiltinKind::bitcrusher);set(crusher,0,4);set(crusher,1,48000);set(crusher,4,100);crusher.prepareToPlay(48000,4096);auto crushed=sine(4096);crusher.processBlock(crushed,midi);for(int n=0;n<4096;++n)check(std::abs(crushed.getSample(0,n)*8-std::round(crushed.getSample(0,n)*8))<1e-5,"Bitcrusher quantisation incorrect");
    BuiltinEffect delay(BuiltinKind::tempoDelay);set(delay,0,10);set(delay,3,0);set(delay,4,20);set(delay,5,20000);set(delay,7,100);delay.prepareToPlay(48000,48000);juce::AudioBuffer<float> impulse(2,48000);impulse.clear();impulse.setSample(0,0,1);delay.processBlock(impulse,midi);check(impulse.getMagnitude(0,0,480)==0 && impulse.getMagnitude(0,480,100)> .1f,"Delay impulse timing incorrect");Tempo tempo;tempo.tempo=150;delay.setPlayHead(&tempo);set(delay,1,1);set(delay,2,5);delay.prepareToPlay(48000,48000);impulse.clear();impulse.setSample(0,0,1);delay.processBlock(impulse,midi);check(impulse.getMagnitude(0,0,19200)==0 && impulse.getMagnitude(0,19200,100)>.1f,"Delay did not synchronise to host tempo");delay.setPlayHead(nullptr);
    BuiltinEffect ducker(BuiltinKind::ducker);auto buses=ducker.getBusesLayout();buses.inputBuses.set(1,juce::AudioChannelSet::stereo());check(ducker.setBusesLayout(buses),"Ducker sidechain not enabled");ducker.prepareToPlay(48000,4096);juce::AudioBuffer<float> sidechain(4,4096);for(int n=0;n<4096;++n){sidechain.setSample(0,n,.5f);sidechain.setSample(1,n,.5f);sidechain.setSample(2,n,.5f);sidechain.setSample(3,n,.5f);}ducker.processBlock(sidechain,midi);check(sidechain.getSample(0,4000)<.15f && ducker.reduction.load()>10,"Sidechain did not duck main signal");ducker.reset();sidechain.clear();for(int n=0;n<4096;++n)sidechain.setSample(0,n,.5f);ducker.processBlock(sidechain,midi);check(sidechain.getSample(0,4000)==.5f,"Ducker reacted without external source");
    BuiltinEffect room(BuiltinKind::room);set(room,4,100);room.prepareToPlay(48000,48000);impulse.clear();impulse.setSample(0,0,1);impulse.setSample(1,0,1);room.processBlock(impulse,midi);check(impulse.getMagnitude(0,3000,30000)> .0001f,"Room produced no reverberation tail");
    BuiltinEffect resonator(BuiltinKind::resonator);set(resonator,4,100);resonator.prepareToPlay(48000,48000);impulse.clear();impulse.setSample(0,0,1);resonator.processBlock(impulse,midi);check(impulse.getMagnitude(0,100,1000)> .000001f && rms(impulse,24000)<.0001f,"Resonator tail missing or unstable");
    BuiltinEffect shifter(BuiltinKind::frequencyShifter);set(shifter,0,250);set(shifter,2,100);shifter.prepareToPlay(48000,48000);auto shifted=sine(48000,1000);shifter.processBlock(shifted,midi);auto magnitude=[&](double hz){double real=0,imag=0;for(int n=5000;n<45000;++n){double phase=juce::MathConstants<double>::twoPi*hz*n/48000;real+=shifted.getSample(0,n)*std::cos(phase);imag+=shifted.getSample(0,n)*std::sin(phase);}return std::hypot(real,imag);};check(magnitude(1250)>magnitude(750)*10 && magnitude(1250)>magnitude(1000)*10,"Frequency shifter did not shift the spectrum upwards");
    {BuiltinEffect normal(BuiltinKind::compressor),filtered(BuiltinKind::compressor);for(auto* p:{&normal,&filtered}){set(*p,0,-30);set(*p,1,10);set(*p,2,.1f);set(*p,6,0);}set(filtered,7,1000);normal.prepareToPlay(48000,48000);filtered.prepareToPlay(48000,48000);auto low=sine(48000,50),copy=low;normal.processBlock(low,midi);filtered.processBlock(copy,midi);check(rms(copy,24000)>rms(low,24000)*3,"Compressor detector filter did not reject bass");}
    {DrumAudioProcessor p;auto& library=p.getLibrary();auto state=library.snapshot();auto kit=state.activeKit,group=state.kits[0].groups[0].id;auto source=library.addInstrument(kit,group).id,target=library.addInstrument(kit,group).id;
        auto file=juce::File::getCurrentWorkingDirectory().getChildFile("creative-sidechain-test.wav");juce::WavAudioFormat format;std::unique_ptr<juce::AudioFormatWriter> writer(format.createWriterFor(file.createOutputStream().release(),48000,1,24,{},0));check(writer!=nullptr,"Sidechain fixture writer failed");juce::AudioBuffer<float> constant(1,48000);for(int n=0;n<48000;++n)constant.setSample(0,n,.25f);writer->writeFromAudioSampleBuffer(constant,0,48000);writer.reset();p.getSampleEngine().requestLoad(kit,source,file);p.getSampleEngine().requestLoad(kit,target,file);check(p.getSampleEngine().waitForLoading(10000),"Sidechain fixtures failed to load");auto added=p.getEffects().add(kit,target,builtinDescription(BuiltinKind::ducker));check(added.ok,"Cannot add ducker to instrument");check(p.getEffects().sidechain(kit,target,added.id,21,0,1,false).ok,"Cannot select drum sidechain source");p.getEffects().sync();p.prepareToPlay(48000,512);check(p.getEffects().supportsSidechain(added.id),"Hosted built-in ducker lost sidechain bus");check(p.getSampleEngine().waitForLoading(10000),"Sidechain instrument bank timed out");juce::AudioBuffer<float> output(2,512);juce::MidiBuffer notes;notes.addEvent(juce::MidiMessage::noteOn(1,21,(juce::uint8)127),0);notes.addEvent(juce::MidiMessage::noteOn(1,22,(juce::uint8)127),0);for(int n=0;n<20;++n){output.clear();p.processBlock(output,notes);notes.clear();}check(output.getSample(0,500)>.29f && output.getSample(0,500)<.35f,"Instrument-to-instrument ducking failed in hosted chain");p.releaseResources();file.deleteFile();}
    for(int character=0;character<3;++character){BuiltinEffect saturation(BuiltinKind::saturation);set(saturation,0,30);set(saturation,3,(float)character);saturation.prepareToPlay(48000,4096);auto b=sine(4096);saturation.processBlock(b,midi);check(b.getMagnitude(0,4096)<2.1f,"Saturation character has unsafe normalisation");saturation.reset();b.clear();saturation.processBlock(b,midi);check(b.getMagnitude(0,4096)==0,"Saturation character generated audio from silence");}
    BuiltinEffect comparison(BuiltinKind::utility);set(comparison,0,6);comparison.swapComparison();set(comparison,0,-6);comparison.swapComparison();check(comparison.controls[0]->get()==6,"A/B did not restore A");comparison.swapComparison();check(comparison.controls[0]->get()==-6,"A/B did not restore B");comparison.prepareToPlay(48000,48000);comparison.levelMatch.store(true);auto dry=sine(48000);auto wet=dry;comparison.processBlock(wet,midi);check(std::abs(rms(wet,30000)-rms(dry,30000))<.01f,"Level match did not equalise RMS");comparison.auditionBypass.store(true);wet=dry;comparison.processBlock(wet,midi);check(std::abs(wet.getSample(0,47000)-dry.getSample(0,47000))<1e-5,"Comparison bypass is not dry audio");juce::MemoryBlock saved;comparison.getStateInformation(saved);BuiltinEffect recall(BuiltinKind::utility);recall.setStateInformation(saved.getData(),(int)saved.getSize());check(!recall.levelMatch.load() && !recall.auditionBypass.load(),"Listening tools persisted into saved effect");
    for(auto kind:{BuiltinKind::compressor,BuiltinKind::saturation}){BuiltinEffect modern(kind);juce::MemoryBlock state;modern.getStateInformation(state);auto xml=juce::AudioProcessor::getXmlFromBinary(state.getData(),(int)state.getSize());xml->setAttribute("version",2);int count=kind==BuiltinKind::compressor?7:3;for(int n=count;n<(int)modern.controls.size();++n)xml->removeAttribute("p"+juce::String(n));juce::MemoryBlock legacy;juce::AudioProcessor::copyXmlToBinary(*xml,legacy);modern.setStateInformation(legacy.getData(),(int)legacy.getSize());check(modern.controls.back()->get()==0,"Legacy effect appended parameter not defaulted");}
    for(int n=9;n<builtinCount;++n){BuiltinEffect p((BuiltinKind)n);p.prepareToPlay(48000,512);std::unique_ptr<juce::AudioProcessorEditor> editor(p.createEditor());editor->setSize(900,480);editor->setVisible(true);int maxX=-1,mixX=-1;for(auto* child:editor->getChildren()){if(child->getComponentID().startsWith("builtin-knob-")){maxX=juce::jmax(maxX,child->getX());if(child->getComponentID()=="builtin-knob-Mix")mixX=child->getX();}check(child->getBottom()<=editor->getHeight(),"Effect control clipped at bottom");}check(mixX==maxX,"Creative Mix control not last on right");auto path=juce::File::getCurrentWorkingDirectory().getChildFile("builtin-"+builtinName(p.kind)+".png");path.deleteFile();juce::FileOutputStream out(path);check(juce::PNGImageFormat().writeImageToStream(editor->createComponentSnapshot(editor->getLocalBounds()),out),"Creative editor screenshot failed");}
    std::cout<<"Creative DSP, sidechain, tails, spectrum shifting, compatibility and comparison tools passed\n";
}
